// capacity experiment: infinite gold, full board from wave 1
load('simx.js'); load('strat1.js');
var SEEDS = [1, 2, 3, 5, 8, 13, 99, 1234, 777777, 20240611];
function board(spec) { // spec: string of 16 chars b,c,f,l,k(flak),- ; all T3 (lowercase) or T1 (uppercase)
  var m = { b: 'bolt', c: 'cannon', f: 'frost', l: 'lance', k: 'flak' };
  var o = [], i;
  for (i = 0; i < 16; i++) { var ch = spec[i]; if (ch === '-') continue; o.push([i, m[ch.toLowerCase()]]); }
  for (var r = 0; r < 2; r++) for (i = 0; i < 16; i++) { var ch2 = spec[i]; if (ch2 === '-' || ch2 !== ch2.toLowerCase()) continue; o.push([i, 'up']); }
  return o;
}
function run(spec, extra) {
  var tot = 0, t0 = Date.now(), sc = [];
  for (var k = 0; k < SEEDS.length; k++) {
    STRAT_P = { order: board(spec) };
    if (extra) for (var key in extra) STRAT_P[key] = extra[key];
    var r = rampartSimulate(createStrategy, SEEDS[k], 12020);
    tot += r.score; sc.push(r.score);
  }
  print(spec, (tot / SEEDS.length).toFixed(2), JSON.stringify(extra || {}), (Date.now() - t0) + 'ms', sc.join(' '));
}
var STRAT_P;
var specs = arguments.length ? arguments : ['cccccccccccccccc'];
for (var q = 0; q < specs.length; q++) { run(specs[q]); }

