(function () {
  'use strict';
  var DURATION = 100;
  var TPS = 20;

  // ------------------------------------------------------------------ board constants (render-side geometry only)
  var GROUND = [[50, 250], [650, 250], [650, 1050], [1250, 1050], [1250, 350], [1850, 350], [1850, 1150], [2350, 1150]];
  var AIR = [[50, 650], [2150, 650], [2150, 1150], [2350, 1150]];
  var ROUTES = [GROUND, AIR], ROUTE_LEN = [4600, 2800];
  var SLOTS = [[3, 3], [5, 5], [7, 4], [7, 8], [9, 9], [10, 5], [11, 8], [13, 8], [14, 5], [15, 2], [16, 7], [17, 4], [19, 8], [20, 10], [22, 9], [3, 7]];
  var T_IDX = { bolt: 0, cannon: 1, frost: 2, lance: 3, flak: 4 };
  var E_IDX = { grunt: 0, runner: 1, wisp: 2, brute: 3, splitter: 4, mender: 5, splitling: 6 };
  var E_SPEED = [10, 20, 12, 6, 8, 8, 12];
  var E_AIR = [0, 0, 1, 0, 0, 0, 0];
  var E_TOP = [0.74, 0.5, 1.28, 1.02, 0.72, 0.92, 0.36];           // health-bar height per type
  var E_COL = [[0.48, 0.6, 0.42], [1.0, 0.82, 0.1], [0.25, 0.92, 1.0], [1.0, 0.45, 0.08], [0.66, 0.3, 0.92], [0.92, 0.98, 0.93], [0.8, 0.5, 1.0]];
  var T_COL = [[0.4, 0.62, 1.0], [0.95, 0.6, 0.22], [0.82, 0.95, 1.0], [1.0, 0.12, 0.22], [0.1, 0.85, 0.75]];
  var T_MUZZLE = [0.62, 0.66, 0.95, 1.12, 0.62];

  function routeXY(air, prog, out) {
    var pts = ROUTES[air], d = prog < 0 ? 0 : prog, i, ax, ay, bx, by, seg;
    for (i = 0; i < pts.length - 1; i++) {
      ax = pts[i][0]; ay = pts[i][1]; bx = pts[i + 1][0]; by = pts[i + 1][1];
      seg = Math.abs(bx - ax) + Math.abs(by - ay);
      if (d <= seg || i === pts.length - 2) {
        if (d > seg) d = seg;
        out.x = (ax + (bx > ax ? d : bx < ax ? -d : 0)) / 100;
        out.y = (ay + (by > ay ? d : by < ay ? -d : 0)) / 100;
        return out;
      }
      d -= seg;
    }
    return out;
  }

  // ------------------------------------------------------------------ seeded visual randomness (seed 42)
  function seededFloat(seed) {
    var a = seed | 0;
    return function () {
      a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  var vrand = seededFloat(42);
  var VR = new Float32Array(8192);
  (function () { for (var i = 0; i < VR.length; i++) VR[i] = vrand(); })();
  function vr(a, b) { return VR[(Math.imul(a | 0, 73) + Math.imul(b | 0, 1291) + 17) & 8191]; }
  function noise1(x, ch) { // smooth seeded value noise in [-1,1]
    var i = Math.floor(x), f = x - i, u = f * f * (3 - 2 * f);
    var a = VR[(i * 7 + ch * 977) & 8191], b = VR[((i + 1) * 7 + ch * 977) & 8191];
    return (a + (b - a) * u) * 2 - 1;
  }
  function noise2(x, y) {
    var ix = Math.floor(x), iy = Math.floor(y), fx = x - ix, fy = y - iy;
    var ux = fx * fx * (3 - 2 * fx), uy = fy * fy * (3 - 2 * fy);
    function h(a, b) { return VR[(Math.imul(a, 157) + Math.imul(b, 2633) + 5) & 8191]; }
    var a = h(ix, iy), b = h(ix + 1, iy), c = h(ix, iy + 1), d = h(ix + 1, iy + 1);
    return a + (b - a) * ux + (c - a) * uy + (a - b - c + d) * ux * uy;
  }
  function clamp01(x) { return x < 0 ? 0 : x > 1 ? 1 : x; }
  function smooth(x) { x = clamp01(x); return x * x * (3 - 2 * x); }

  // ------------------------------------------------------------------ replay: run the rules engine once, recording per-tick state
  function buildReplay() {
    var R = {
      eOff: [0], eId: [], eType: [], eProg: [], eHp: [], eSlow: [],
      gold: [], hp: [], wave: [], next: [], tur: [], aim: [], built: [],
      shots: [], kills: [], heals: [], leaks: [], acts: [], spawnTick: {}, fallTick: -1, nFrames: 0
    };
    var curAim = [], curBuilt = [], lastNextRef = null, lastNextCounts = null, s;
    for (s = 0; s < 16; s++) { curAim.push(Math.atan2(-(7 - (SLOTS[s][1] + 0.5)), 12 - (SLOTS[s][0] + 0.5))); curBuilt.push(-1); }
    var rec = {
      frame: function (t, enemies, turrets, gold, baseHp, wave, nextComp, fell) {
        var i, e;
        for (i = 0; i < enemies.length; i++) {
          e = enemies[i];
          R.eId.push(e.id); R.eType.push(E_IDX[e.type]); R.eProg.push(e.progress); R.eHp.push(e.hp > 0 ? e.hp / e.maxHp : 0); R.eSlow.push(e.slow > 0 ? 1 : 0);
          if (R.spawnTick[e.id] === undefined) R.spawnTick[e.id] = t;
        }
        R.eOff.push(R.eId.length);
        R.gold.push(gold); R.hp.push(baseHp < 0 ? 0 : baseHp); R.wave.push(wave);
        if (nextComp !== lastNextRef) {
          lastNextRef = nextComp; lastNextCounts = [0, 0, 0, 0, 0, 0];
          for (i = 0; i < nextComp.length; i++) lastNextCounts[E_IDX[nextComp[i]]]++;
        }
        R.next.push(lastNextCounts);
        for (i = 0; i < 16; i++) {
          var tu = turrets[i];
          R.tur.push(tu ? 1 + T_IDX[tu.type] * 3 + (tu.tier - 1) : 0);
          R.aim.push(curAim[i]); R.built.push(tu ? curBuilt[i] : -1);
        }
        if (fell) R.fallTick = t;
        R.nFrames++;
