  var mean = tot / SEEDS.length;
  print(arguments[a], 'mean', mean.toFixed(3), 'min', mn, 'max', mx, 'sd', Math.sqrt(sq / SEEDS.length - mean * mean).toFixed(2), 'ms/game', ((Date.now() - t0) / SEEDS.length).toFixed(1));
}

