var STRAT_P = JSON.parse(readFile(arguments[0]));
var res = [], tot = 0;
for (var k = 0; k < SEEDS.length; k++) { var s = rampartSimulate(createStrategy, SEEDS[k], 12020).score; res.push([s, SEEDS[k]]); tot += s; }
res.sort(function (a, b) { return a[0] - b[0]; });
print('mean', (tot / N).toFixed(3), 'worst', res.slice(0, 8).map(function (r) { return r[1] + ':' + r[0]; }).join(' '));
for (var q = 0; q < SHOW; q++) {
  var leaks = [], gold = [];
  var rec = {
    leak: function (t, e, hp) { leaks.push(e.type[0] + (e.type === 'splitling' ? 'l' : '') + e.wave + '@' + Math.floor((t - 20) / 40 + 1)); },
