    frame: function (t, en, tu, g, hp, wave) { if (t >= 20 && (t - 20) % 40 === 39) gold.push(g); }
  };
  var r = rampartSimulate(createStrategy, res[q][1], 12020, rec);
  print(res[q][1], r.score, leaks.join(' '));
