import socket, json, sys, time, subprocess, os, base64

class Marionette:
    def __init__(self, port=2828):
        self.s = None
        for _ in range(100):
            try:
                self.s = socket.create_connection(('127.0.0.1', port), timeout=120)
                break
            except OSError:
                time.sleep(0.3)
        if not self.s:
            raise RuntimeError('cannot connect')
        self.buf = b''
        self.id = 0
        self._recv()  # hello

    def _recv(self):
        while b':' not in self.buf:
            self.buf += self.s.recv(65536)
        n, rest = self.buf.split(b':', 1)
        n = int(n)
        while len(rest) < n:
            rest += self.s.recv(1 << 20)
        self.buf = rest[n:]
        return json.loads(rest[:n].decode())

    def cmd(self, name, params=None):
        self.id += 1
        msg = json.dumps([0, self.id, name, params or {}])
        self.s.sendall(('%d:%s' % (len(msg), msg)).encode())
        while True:
            r = self._recv()
            if r[0] == 1 and r[1] == self.id:
                if r[2]:
                    raise RuntimeError(str(r[2]))
                return r[3]

    def js(self, script, args=None, timeout=None):
        return self.cmd('WebDriver:ExecuteScript', {'script': script, 'args': args or []}).get('value')

    def ajs(self, script, args=None):
        return self.cmd('WebDriver:ExecuteAsyncScript', {'script': script, 'args': args or []}).get('value')

    def shot(self, path):
        v = self.cmd('WebDriver:TakeScreenshot', {'full': False}).get('value')
        open(path, 'wb').write(base64.b64decode(v))

def launch(profile, w=1280, h=650):
    env = dict(os.environ)
    for k in ['MOZ_DISABLE_CONTENT_SANDBOX', 'MOZ_DISABLE_GPU_SANDBOX', 'MOZ_DISABLE_RDD_SANDBOX', 'MOZ_DISABLE_SOCKET_PROCESS_SANDBOX', 'MOZ_DISABLE_UTILITY_SANDBOX']:
        env[k] = '1'
    p = subprocess.Popen(['/Applications/Firefox.app/Contents/MacOS/firefox', '--headless', '--marionette', '--profile', profile, '--window-size=%d,%d' % (w, h)], env=env, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    return p

