import json,glob
for f in sorted(glob.glob('r3_*.out')):
    for l in open(f):
        if l.startswith('RESULT'):
            sc=l.split()[1]; p=json.loads(l.split(' ',2)[2])
            json.dump(p,open(f.replace('.out','.json'),'w'))
            print(f, sc, ''.join(t[0] if t!='flak' else 'k' for t in p['types']), 'seq',len(p['seq']), 'repl',p['repl'], [round(x) for x in p['resK']])
